.1" e="T514.TIE0.1">gemacht</ts><nts n="HIAT:ip" id="Seg_2340"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2342" s="T514.TIE0.1" e="T514.TIE0.2">Frau</ts><nts n="HIAT:ip" id="Seg_2343"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2345" s="T514.TIE0.2" e="T515">Kastenhuber</ts><nts n="HIAT:ip" id="Seg_2346"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE0"><ts n="sc" id="Seg_2347" s="T0" e="T1"><ts n="e" id="Seg_2349" s="T0" e="T1">Herr Pofalla wissen Sie, was im Moment n Liter Diesel kostet? </ts></ts><ts n="sc" id="Seg_2350" s="T3" e="T5"><ts n="e" id="Seg_2352" s="T3" e="T4">• • </ts><ts n="e" id="Seg_2354" s="T4" e="T5">Wieviel? </ts></ts><ts n="sc" id="Seg_2355" s="T8" e="T14"><ts n="e" id="Seg_2357" s="T8" e="T9">• • </ts><ts n="e" id="Seg_2359" s="T9" e="T10">Eins dreiunddreißig sinds. </ts><ts n="e" id="Seg_2361" s="T10" e="T11">So ist der Bundesdurchschnitt </ts><ts n="e" id="Seg_2363" s="T11" e="T12">Sie ham vielleicht ne günstige Tankstelle in Berlin. </ts><ts n="e" id="Seg_2365" s="T12" e="T13">((atmet ein)) </ts><ts n="e" id="Seg_2367" s="T13" e="T14">Was macht das mit Ihrem Budget? </ts></ts><ts n="sc" id="Seg_2368" s="T17" e="T22"><ts n="e" id="Seg_2370" s="T17" e="T18">((1,3s)) </ts><ts n="e" id="Seg_2372" s="T18" e="T19">Wie das frag ich lieber Frau Kastenhuber. </ts><ts n="e" id="Seg_2374" s="T19" e="T20">Wie wirkt sich die Dieselpreiserhöhung auf </ts><ts n="e" id="Seg_2376" s="T20" e="T21">Sie </ts><ts n="e" id="Seg_2378" s="T21" e="T22">aus? </ts></ts><ts n="sc" id="Seg_2379" s="T29" e="T31"><ts n="e" id="Seg_2381" s="T29" e="T30">• • • </ts><ts n="e" id="Seg_2383" s="T30" e="T31">Es ist nicht mehr drin. </ts></ts><ts n="sc" id="Seg_2384" s="T33" e="T50"><ts n="e" id="Seg_2386" s="T33" e="T34">• • </ts><ts n="e" id="Seg_2388" s="T34" e="T35">Ḿhm̀˙ </ts><ts n="e" id="Seg_2390" s="T35" e="T36">• • </ts><ts n="e" id="Seg_2392" s="T36" e="T37">Ich spar mir jetzt das Kompliment, was man auch machen </ts><ts n="e" id="Seg_2394" s="T37" e="T38">könnte. </ts><ts n="e" id="Seg_2396" s="T38" e="T39">Lassen wirs einfach mal. </ts><ts n="e" id="Seg_2398" s="T39" e="T40">((atmet ein)) </ts><ts n="e" id="Seg_2400" s="T40" e="T41">Ähmm˙ </ts><ts n="e" id="Seg_2402" s="T41" e="T42">• • </ts><ts n="e" id="Seg_2404" s="T42" e="T43">Frau Bartel der Dieselpreis für Kastenhubers das sind für Sie die Energiekosten Strom und Heizung. </ts><ts n="e" id="Seg_2406" s="T43" e="T44">((atmet ein)) </ts><ts n="e" id="Seg_2408" s="T44" e="T45">Und </ts><ts n="e" id="Seg_2410" s="T45" e="T46">die sind in den letzten Jahren um </ts><ts n="e" id="Seg_2412" s="T46" e="T47">fünfundsechzig </ts><ts n="e" id="Seg_2414" s="T47" e="T48">Prozent • • gestiegen. </ts><ts n="e" id="Seg_2416" s="T48" e="T49">Wie v</ts><ts n="e" id="Seg_2418" s="T49" e="T50">erändern diese gestiegenen • Heiz- und und Stromkosten Ihr Leben? </ts></ts><ts n="sc" id="Seg_2419" s="T61" e="T64"><ts n="e" id="Seg_2421" s="T61" e="T62">• • </ts><ts n="e" id="Seg_2423" s="T62" e="T63">Wie mach</ts><ts n="e" id="Seg_2425" s="T63" e="T64">en Sie das denn? </ts></ts><ts n="sc" id="Seg_2426" s="T75" e="T81"><ts n="e" id="Seg_2428" s="T75" e="T76">• • </ts><ts n="e" id="Seg_2430" s="T76" e="T77">Ḿhm̀˙ </ts><ts n="e" id="Seg_2432" s="T77" e="T78">• • </ts><ts n="e" id="Seg_2434" s="T78" e="T79">((atmet ein)) </ts><ts n="e" id="Seg_2436" s="T79" e="T80">Das ist keine Marotte, sondern </ts><ts n="e" id="Seg_2438" s="T80" e="T81">äh… </ts></ts><ts n="sc" id="Seg_2439" s="T82" e="T84"><ts n="e" id="Seg_2441" s="T82" e="T83">• • </ts><ts n="e" id="Seg_2443" s="T83" e="T84">Weil Sie sonst nich hinkommen? </ts></ts><ts n="sc" id="Seg_2444" s="T85" e="T87"><ts n="e" id="Seg_2446" s="T85" e="T86">• </ts><ts n="e" id="Seg_2448" s="T86" e="T87">Ḿhm̀˙ </ts></ts><ts n="sc" id="Seg_2449" s="T91" e="T92"><ts n="e" id="Seg_2451" s="T91" e="T92">Euro. </ts></ts><ts n="sc" id="Seg_2452" s="T99" e="T108"><ts n="e" id="Seg_2454" s="T99" e="T100">((atmet ein)) </ts><ts n="e" id="Seg_2456" s="T100" e="T101">Wie das genau bei Ihnen mit den Finanzen aussieht, das gucken wir uns äh </ts><ts n="e" id="Seg_2458" s="T101" e="T102">gleich </ts><ts n="e" id="Seg_2460" s="T102" e="T103">noch mal an. </ts><ts n="e" id="Seg_2462" s="T103" e="T104">Herr Pofalla es berichteten eine ehemalige Buchhändlerin </ts><ts n="e" id="Seg_2464" s="T104" e="T105">((atmet ein)) </ts><ts n="e" id="Seg_2466" s="T105" e="T106">und eine arbeitende Mutter von drei Kindern aus einem Doppelverdienerhaushalt. </ts><ts n="e" id="Seg_2468" s="T106" e="T107">Wie würden Sie jetzt die Frage beantworten "Wie geht es der Mittelschicht in Deutschland"? </ts><ts n="e" id="Seg_2470" s="T107" e="T108">Sie sind da eingerahmt • • von der Mittelschicht. </ts></ts><ts n="sc" id="Seg_2471" s="T129" e="T134"><ts n="e" id="Seg_2473" s="T129" e="T130">Sie sprechen </ts><ts n="e" id="Seg_2475" s="T130" e="T131">jetzt über eine Politik von mehreren Jahrzehnten, aber Sie waren ja nicht im Ausland und sind jetzt gerade zurückgekommen </ts><ts n="e" id="Seg_2477" s="T131" e="T132">und stel</ts><ts n="e" id="Seg_2479" s="T132" e="T133">len das fest, sondern Sie waren dabei auch. </ts><ts n="e" id="Seg_2481" s="T133" e="T134">((unv.)) </ts></ts><ts n="sc" id="Seg_2482" s="T135" e="T136"><ts n="e" id="Seg_2484" s="T135" e="T136">(Ja). </ts></ts><ts n="sc" id="Seg_2485" s="T139" e="T140"><ts n="e" id="Seg_2487" s="T139" e="T140">(Ja). </ts></ts><ts n="sc" id="Seg_2488" s="T153" e="T156"><ts n="e" id="Seg_2490" s="T153" e="T154">F/ Frau Engelen-Käfer äh ich hab eben diese Schlagzeile aus em Kölner Stadtanzeiger zitiert: </ts><ts n="e" id="Seg_2492" s="T154" e="T155">"Der Absturz der Mittelschicht.". </ts><ts n="e" id="Seg_2494" s="T155" e="T156">Is • • das in Ihren Augen so dramatisch wies klingt? </ts></ts><ts n="sc" id="Seg_2495" s="T175" e="T180"><ts n="e" id="Seg_2497" s="T175" e="T176">Da sind Sie ja gerade in der großen Koalition </ts><ts n="e" id="Seg_2499" s="T176" e="T177">ähm Po</ts><ts n="e" id="Seg_2501" s="T177" e="T178">falla </ts><ts n="e" id="Seg_2503" s="T178" e="T179">auch mit diesem Statement. </ts><ts n="e" id="Seg_2505" s="T179" e="T180">Herr Bahr… </ts></ts><ts n="sc" id="Seg_2506" s="T182" e="T183"><ts n="e" id="Seg_2508" s="T182" e="T183">Is klar. </ts></ts><ts n="sc" id="Seg_2509" s="T187" e="T188"><ts n="e" id="Seg_2511" s="T187" e="T188">Geschenkt. </ts></ts><ts n="sc" id="Seg_2512" s="T189" e="T195"><ts n="e" id="Seg_2514" s="T189" e="T190">Herr Bahr haben </ts><ts n="e" id="Seg_2516" s="T190" e="T191">Sie eigentlich eine Erklärung dafür, warum in diesem Land so </ts><ts n="e" id="Seg_2518" s="T191" e="T192">((atmet ein)) </ts><ts n="e" id="Seg_2520" s="T192" e="T193">so erbittert über Hartz Vier diskutiert worden ist, leidenschaftlich sicher auch in Teilen berechtigt, </ts><ts n="e" id="Seg_2522" s="T193" e="T194">((atmet ein)) </ts><ts n="e" id="Seg_2524" s="T194" e="T195">aber dass diese sogenannte Mittelschicht so lange stillgehalten hat? </ts></ts><ts n="sc" id="Seg_2525" s="T238" e="T258"><ts n="e" id="Seg_2527" s="T238" e="T239">Sie haben meine Frage nur in Teilen beantwortet. </ts><ts n="e" id="Seg_2529" s="T239" e="T240">Sie haben gesacht, </ts><ts n="e" id="Seg_2531" s="T240" e="T241">äh auch wir sind Schuld daran von Hart aber fair, dass wir so wenig Sendungen darüber gemacht haben. </ts><ts n="e" id="Seg_2533" s="T241" e="T242">Man kann Sendungen über Themen machen, </ts><ts n="e" id="Seg_2535" s="T242" e="T243">((atmet ein)) </ts><ts n="e" id="Seg_2537" s="T243" e="T244">die auch Menschen </ts><ts n="e" id="Seg_2539" s="T244" e="T245">spüren. </ts><ts n="e" id="Seg_2541" s="T245" e="T246">Deswegen möcht ich Frau </ts><ts n="e" id="Seg_2543" s="T246" e="T247">Kastenhuber </ts><ts n="e" id="Seg_2545" s="T247" e="T248">mal ffragen, ähm </ts><ts n="e" id="Seg_2547" s="T248" e="T249">((atmet ein)) </ts><ts n="e" id="Seg_2549" s="T249" e="T250">warum von den Kastenhubers dieser Welt so lange nichts • • • zu hören war. </ts><ts n="e" id="Seg_2551" s="T250" e="T251">Lags vielleicht daran, dass Sie sich nicht getraut haben </ts><ts n="e" id="Seg_2553" s="T251" e="T252">((atmet ein)) </ts><ts n="e" id="Seg_2555" s="T252" e="T253">zu sagen, dass Sie mit dreitausendfünfhundert euro netto kaum hinkommen, </ts><ts n="e" id="Seg_2557" s="T253" e="T254">dass das ne Zahl is, die Ihnen selbst so hoch </ts><ts n="e" id="Seg_2559" s="T254" e="T255">erscheint, </ts><ts n="e" id="Seg_2561" s="T255" e="T256">dass Sie sagen </ts><ts n="e" id="Seg_2563" s="T256" e="T257">((atmet ein)) </ts><ts n="e" id="Seg_2565" s="T257" e="T258">kann man nicht mit rausgehen. </ts></ts><ts n="sc" id="Seg_2566" s="T277" e="T278"><ts n="e" id="Seg_2568" s="T277" e="T278">Ḿhm̀˙ </ts></ts><ts n="sc" id="Seg_2569" s="T285" e="T287"><ts n="e" id="Seg_2571" s="T285" e="T286">Vielleich</ts><ts n="e" id="Seg_2573" s="T286" e="T287">t ((unv.))… </ts></ts><ts n="sc" id="Seg_2574" s="T289" e="T302"><ts n="e" id="Seg_2576" s="T289" e="T290">Vielleicht äh Politiker sind immer äh dann auch richtig bei der Sache, </ts><ts n="e" id="Seg_2578" s="T290" e="T291">wenn sie n Haushaltsplan sehen. </ts><ts n="e" id="Seg_2580" s="T291" e="T292">Vielleicht </ts><ts n="e" id="Seg_2582" s="T292" e="T293">sollte </ts><ts n="e" id="Seg_2584" s="T293" e="T294">man den Haushaltsplan der Familie Kastenhuber </ts><ts n="e" id="Seg_2586" s="T294" e="T295">((atmet ein)) </ts><ts n="e" id="Seg_2588" s="T295" e="T296">den aktuellen mal offenlegen, </ts><ts n="e" id="Seg_2590" s="T296" e="T297">((atmet ein)) </ts><ts n="e" id="Seg_2592" s="T297" e="T298">um zu be… </ts><ts n="e" id="Seg_2594" s="T298" e="T299">Können Sie das überhaupt glauben, </ts><ts n="e" id="Seg_2596" s="T299" e="T300">dass man von dreitausendfünfhundert euro netto ähm mit ner Familie drei Kinder(n) nicht hinkommt? </ts><ts n="e" id="Seg_2598" s="T300" e="T301">Können sie das glau</ts><ts n="e" id="Seg_2600" s="T301" e="T302">ben? </ts></ts><ts n="sc" id="Seg_2601" s="T304" e="T306"><ts n="e" id="Seg_2603" s="T304" e="T305">(Wo </ts><ts n="e" id="Seg_2605" s="T305" e="T306">macht) ((unv.))… </ts></ts><ts n="sc" id="Seg_2606" s="T380" e="T390"><ts n="e" id="Seg_2608" s="T380" e="T381">• • • </ts><ts n="e" id="Seg_2610" s="T381" e="T382">Und dann </ts><ts n="e" id="Seg_2612" s="T382" e="T383">ham Sie geholfen, </ts><ts n="e" id="Seg_2614" s="T383" e="T384">ham Sie noch geholfen in der Fabrik wahrscheinlich. </ts><ts n="e" id="Seg_2616" s="T384" e="T385">((atmet ein)) </ts><ts n="e" id="Seg_2618" s="T385" e="T386">(Ich woll)… </ts><ts n="e" id="Seg_2620" s="T386" e="T387">Es </ts><ts n="e" id="Seg_2622" s="T387" e="T388">warn aber auch </ts><ts n="e" id="Seg_2624" s="T388" e="T389">andere Zeiten. </ts><ts n="e" id="Seg_2626" s="T389" e="T390">Das muss man ja auch mal… </ts></ts><ts n="sc" id="Seg_2627" s="T391" e="T396"><ts n="e" id="Seg_2629" s="T391" e="T392">Da/ </ts><ts n="e" id="Seg_2631" s="T392" e="T393">dass Sie da viel leisten mussten </ts><ts n="e" id="Seg_2633" s="T393" e="T394">is ja klar, </ts><ts n="e" id="Seg_2635" s="T394" e="T395">aber ich denke, dass Sie sich </ts><ts n="e" id="Seg_2637" s="T395" e="T396">mit den Kastenhubers. </ts></ts><ts n="sc" id="Seg_2638" s="T401" e="T404"><ts n="e" id="Seg_2640" s="T401" e="T402">Ham sie den letzten Satz </ts><ts n="e" id="Seg_2642" s="T402" e="T403">gehört "Da war mehr Menschlichkeit"? </ts><ts n="e" id="Seg_2644" s="T403" e="T404">((unv.))… </ts></ts><ts n="sc" id="Seg_2645" s="T452" e="T466"><ts n="e" id="Seg_2647" s="T452" e="T453">(Und) tun Sie/ tun Sie mir einen Ge</ts><ts n="e" id="Seg_2649" s="T453" e="T454">fallen, wenn Sie alles gut machen </ts><ts n="e" id="Seg_2651" s="T454" e="T455">wollen, </ts><ts n="e" id="Seg_2653" s="T455" e="T456">dann tun Sie es </ts><ts n="e" id="Seg_2655" s="T456" e="T457">unserm Toninge</ts><ts n="e" id="Seg_2657" s="T457" e="T458">nieur </ts><ts n="e" id="Seg_2659" s="T458" e="T459">nicht </ts><ts n="e" id="Seg_2661" s="T459" e="T460">aufs Mikro hauen, sonst </ts><ts n="e" id="Seg_2663" s="T460" e="T462">äh hat der </ts><ts n="e" id="Seg_2665" s="T462" e="T463">Ton</ts><ts n="e" id="Seg_2667" s="T463" e="T464">ingenieur bald nen </ts><ts n="e" id="Seg_2669" s="T464" e="T465">((atmet ein)) </ts><ts n="e" id="Seg_2671" s="T465" e="T466">Hörgerät • ((lacht))˙ </ts></ts><ts n="sc" id="Seg_2672" s="T467" e="T468"><ts n="e" id="Seg_2674" s="T467" e="T468">Is… </ts></ts><ts n="sc" id="Seg_2675" s="T475" e="T487"><ts n="e" id="Seg_2677" s="T475" e="T476">Dann </ts><ts n="e" id="Seg_2679" s="T476" e="T477">schaun‿wer mal an, </ts><ts n="e" id="Seg_2681" s="T477" e="T478">wie sie diesem </ts><ts n="e" id="Seg_2683" s="T478" e="T479">• Druck versuchen standzuhalten </ts><ts n="e" id="Seg_2685" s="T479" e="T480">((1,5s)) </ts><ts n="e" id="Seg_2687" s="T480" e="T481">und schaun wir jetzt mal </ts><ts n="e" id="Seg_2689" s="T481" e="T482">• • </ts><ts n="e" id="Seg_2691" s="T482" e="T483">in Ihren Haushaltsplan, wo bei Ihnen das Geld bleibt, </ts><ts n="e" id="Seg_2693" s="T483" e="T484">die dreitausendfünfhundert euro netto. </ts><ts n="e" id="Seg_2695" s="T484" e="T485">Ich nenn diese Summe nochmal. </ts><ts n="e" id="Seg_2697" s="T485" e="T486">((atmet ein)) </ts><ts n="e" id="Seg_2699" s="T486" e="T487">Gucken‿wer mal, was draus wird. </ts></ts><ts n="sc" id="Seg_2700" s="T489" e="T492"><ts n="e" id="Seg_2702" s="T489" e="T490">Herr Bahr Hartz Vier Haushalten wird auch zugemutet, dass sie ihr Vermögen einbringen. </ts><ts n="e" id="Seg_2704" s="T490" e="T491">Dieses Beispiel jetzt: • Klavier gegen Zahnspange. </ts><ts n="e" id="Seg_2706" s="T491" e="T492">Geht das für Sie in Ordnung? </ts></ts><ts n="sc" id="Seg_2707" s="T511" e="T515"><ts n="e" id="Seg_2709" s="T511" e="T512">Warum ham </ts><ts n="e" id="Seg_2711" s="T512" e="T513">Sie‿s </ts><ts n="e" id="Seg_2713" s="T513" e="T514">nicht ge</ts><ts n="e" id="Seg_2715" s="T514" e="T515">macht Frau Kastenhuber </ts></ts></segmentation><annotation name="en" tierref="TIE18"><ta id="Seg_2716" s="T0" e="T1">Mr Pofalla, do you know how much a litre of diesel costs at the moment? </ta><ta id="Seg_2717" s="T3" e="T5">How much ? </ta><ta id="Seg_2718" s="T8" e="T10">One thirty-three is it . </ta><ta id="Seg_2719" s="T10" e="T11">That's the national average </ta><ta id="Seg_2720" s="T11" e="T12">You might have a cheap petrol station in Berlin . </ta><ta id="Seg_2721" s="T12" e="T14">What does that do to your budget? </ta><ta id="Seg_2722" s="T17" e="T19">How, I would rather like to ask Mrs Kastenhuber this. </ta><ta id="Seg_2723" s="T19" e="T22">How does the diesel price increase affect you? </ta><ta id="Seg_2724" s="T29" e="T31">There is no more in it . </ta><ta id="Seg_2725" s="T33" e="T38">Ḿhm̀ ˙ I'll save the compliments now, which you could also do. </ta><ta id="Seg_2726" s="T38" e="T39">Let's just leave it at that . </ta><ta id="Seg_2727" s="T39" e="T42">Umm </ta><ta id="Seg_2728" s="T42" e="T43">Mrs Bartel the diesel price for Kastenhubers is the energy costs for electricity and heating for you . </ta><ta id="Seg_2729" s="T43" e="T48">And these have risen by sixty-five per cent in recent years . </ta><ta id="Seg_2730" s="T48" e="T50">How have these increased heating and electricity costs changed your life? </ta><ta id="Seg_2731" s="T61" e="T64">How do you do that? </ta><ta id="Seg_2732" s="T75" e="T77">Ḿhm̀ </ta><ta id="Seg_2733" s="T77" e="T81">That's not a quirk, but er ...</ta><ta id="Seg_2734" s="T82" e="T84">Because you don't get along otherwise? </ta><ta id="Seg_2735" s="T85" e="T87">Ḿhm̀ ˙</ta><ta id="Seg_2736" s="T91" e="T92">Euro . </ta><ta id="Seg_2737" s="T99" e="T103">Let's take another look at exactly what your finances look like . </ta><ta id="Seg_2738" s="T103" e="T106">Mr Pofalla, a former bookseller and a working mother of three children from a dual-income household reported . </ta><ta id="Seg_2739" s="T106" e="T107">How would you now answer the question " How is the middle class in Germany " ? </ta><ta id="Seg_2740" s="T107" e="T108">You are surrounded by the middle class . </ta><ta id="Seg_2741" s="T129" e="T133">You are now talking about a policy spanning several decades, but you were not abroad and have just come back and realised that, you were there too. </ta><ta id="Seg_2742" s="T135" e="T136">Yes .</ta><ta id="Seg_2743" s="T139" e="T140">Yes .</ta><ta id="Seg_2744" s="T153" e="T155">Q / Mrs Engelen-Käfer er I just quoted this headline from the Kölner Stadtanzeiger : " The crash of the middle class . " . </ta><ta id="Seg_2745" s="T155" e="T156">Is that as dramatic as it sounds in your eyes ? </ta><ta id="Seg_2746" s="T175" e="T179">You're in the grand coalition, Mr Pofalla, with this statement. </ta><ta id="Seg_2747" s="T179" e="T180">Mr Bahr ...</ta><ta id="Seg_2748" s="T182" e="T183">That's clear . </ta><ta id="Seg_2749" s="T187" e="T188">Gifted . </ta><ta id="Seg_2750" s="T189" e="T195">Mr Bahr, do you actually have an explanation for why Hartz Four has been so bitterly debated in this country, passionately and certainly justified in parts, but that this so-called middle class has kept quiet for so long? </ta><ta id="Seg_2751" s="T238" e="T239">You only answered my question in part . </ta><ta id="Seg_2752" s="T239" e="T241">You said that we at Hart aber fair are also to blame for the fact that we have made so few programmes about it. </ta><ta id="Seg_2753" s="T241" e="T245">You can make programmes about topics that people also feel. </ta><ta id="Seg_2754" s="T245" e="T250">That's why I'd like to ask Mrs Kastenhuber why nothing has been heard from the Kastenhubers of this world for so long. </ta><ta id="Seg_2755" s="T250" e="T258">Is it perhaps because you haven't dared to say that you can barely get by on three thousand five hundred euros net, that this is a figure that seems so high to you that you say you can't go out with it? </ta><ta id="Seg_2756" s="T277" e="T278">Ḿhm̀ ˙</ta><ta id="Seg_2757" s="T285" e="T287">Maybe ...</ta><ta id="Seg_2758" s="T289" e="T291">Maybe politicians are always right on the ball when they see a budget. </ta><ta id="Seg_2759" s="T291" e="T298">Perhaps the budget of the Kastenhuber family should be disclosed to the current ones in order to ... </ta><ta id="Seg_2760" s="T298" e="T300">Can you even believe that a family with three children can't get by on three thousand five hundred euros net ? </ta><ta id="Seg_2761" s="T300" e="T302">Can you believe that ? </ta><ta id="Seg_2762" s="T304" e="T306">Where does ...</ta><ta id="Seg_2763" s="T380" e="T384">And then you helped, you probably still helped in the factory. </ta><ta id="Seg_2764" s="T384" e="T386">I wanted to ... </ta><ta id="Seg_2765" s="T386" e="T389">But there were other times too . </ta><ta id="Seg_2766" s="T389" e="T390">You have to ...</ta><ta id="Seg_2767" s="T391" e="T396">It's clear that you had to do a lot there, but I think that you are on the same page as the Kastenhubers. </ta><ta id="Seg_2768" s="T401" e="T404">Did you hear the last sentence "There was more humanity"? ...</ta><ta id="Seg_2769" s="T452" e="T466">And do / do me a favour, if you want to do everything well, then don't hit our sound engineer on the microphone, otherwise the sound engineer will soon have a hearing aid ˙.</ta><ta id="Seg_2770" s="T467" e="T468">Is ...</ta><ta id="Seg_2771" s="T475" e="T484">Then let's take a look at how you try to withstand this pressure and let's take a look at your budget to see where the money remains, the three thousand five hundred euros net. </ta><ta id="Seg_2772" s="T484" e="T485">I'll mention this sum again. </ta><ta id="Seg_2773" s="T485" e="T487">Let's see what happens to it. </ta><ta id="Seg_2774" s="T489" e="T490">Mr Bahr Hartz Vier households are also expected to contribute their assets. </ta><ta id="Seg_2775" s="T490" e="T491">This example now: piano for braces . </ta><ta id="Seg_2776" s="T491" e="T492">Is that okay with you ? </ta><ta id="Seg_2777" s="T511" e="T515">Why didn't you do it, Mrs Kastenhuber?</ta></annotation><annotation name="akz" tierref="TIE1"><ta id="Seg_2778" s="T20" e="T21">—</ta><ta id="Seg_2779" s="T46" e="T47">—</ta><ta id="Seg_2780" s="T187" e="T188">—</ta><ta id="Seg_2781" s="T244" e="T245">—</ta></annotation><annotation name="k" tierref="TIE13"><ta id="Seg_2782" s="T34" e="T35">bejahend </ta><ta id="Seg_2783" s="T76" e="T77">bejahend </ta><ta id="Seg_2784" s="T86" e="T87">bejahend </ta><ta id="Seg_2785" s="T277" e="T278">bejahend </ta><ta id="Seg_2786" s="T393" e="T394">schnell </ta></annotation></segmented-tier><segmented-tier id="TIE2" speaker="SPK1" category="v" type="t" display-name="RP [v]"><timeline-fork start="T1" end="T2"><tli id="T1.TIE2.1"/>
