_5561"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_5563" s="T524" e="T524.TIE4.1">is</ts><nts n="HIAT:ip" id="Seg_5564">‿</nts><ts n="HIAT:w" id="Seg_5566" s="T524.TIE4.1" e="T524.TIE4.2">es</ts><nts n="HIAT:ip" id="Seg_5567"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_5569" s="T524.TIE4.2" e="T524.TIE4.3">so</ts><nts n="HIAT:ip" id="Seg_5570">,</nts><nts n="HIAT:ip" id="Seg_5571"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_5573" s="T524.TIE4.3" e="T524.TIE4.4">dass</ts><nts n="HIAT:ip" id="Seg_5574"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_5576" s="T524.TIE4.4" e="T524.TIE4.5">nur</ts><nts n="HIAT:ip" id="Seg_5577"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_5579" s="T524.TIE4.5" e="T525">bei</ts><nts n="HIAT:ip" id="Seg_5580"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_5582" s="T525" e="T526">Überbiss</ts><nts n="HIAT:ip" id="Seg_5583"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_5585" s="T526" e="T526.TIE4.1">bei</ts><nts n="HIAT:ip" id="Seg_5586"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_5588" s="T526.TIE4.1" e="T526.TIE4.2">ner</ts><nts n="HIAT:ip" id="Seg_5589"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_5591" s="T526.TIE4.2" e="T527">best</ts><nts n="HIAT:ip" id="Seg_5592">…</nts><nts n="HIAT:ip" id="Seg_5593"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE4"><ts n="sc" id="Seg_5594" s="T22" e="T29"><ts n="e" id="Seg_5596" s="T22" e="T23">• • </ts><ts n="e" id="Seg_5598" s="T23" e="T24">Also bei uns in Bayern wars heut früh eins sechsunddreißig </ts><ts n="e" id="Seg_5600" s="T24" e="T25">((atmet ein)) </ts><ts n="e" id="Seg_5602" s="T25" e="T26">äähm und ich werd einfach weiterhin nicht zum Friseur gehen die nächste Zeit, sondern selber schnipseln. </ts><ts n="e" id="Seg_5604" s="T26" e="T27">((lacht))˙ </ts><ts n="e" id="Seg_5606" s="T27" e="T28">• • • </ts><ts n="e" id="Seg_5608" s="T28" e="T29">Ich spars woanders ein. </ts></ts><ts n="sc" id="Seg_5609" s="T31" e="T33"><ts n="e" id="Seg_5611" s="T31" e="T32">((atmet ein)) </ts><ts n="e" id="Seg_5613" s="T32" e="T33">Friseur ist • oft nicht drin. </ts></ts><ts n="sc" id="Seg_5614" s="T37" e="T39"><ts n="e" id="Seg_5616" s="T37" e="T39">((lacht))˙ </ts></ts><ts n="sc" id="Seg_5617" s="T258" e="T289"><ts n="e" id="Seg_5619" s="T258" e="T259">• • </ts><ts n="e" id="Seg_5621" s="T259" e="T260">((atmet ein)) </ts><ts n="e" id="Seg_5623" s="T260" e="T261">Ja mit Sicherheit. </ts><ts n="e" id="Seg_5625" s="T261" e="T262">Also zum einen auch das Verständnis für die Menschen, die mit Hartz Vier leben. </ts><ts n="e" id="Seg_5627" s="T262" e="T263">Auf jeden Fall. </ts><ts n="e" id="Seg_5629" s="T263" e="T264">Also ich denke, das is auch Thema, das darf man nich vergessen, </ts><ts n="e" id="Seg_5631" s="T264" e="T265">((atmet ein)) </ts><ts n="e" id="Seg_5633" s="T265" e="T266">aber das andere is auch, dass man natürlich </ts><ts n="e" id="Seg_5635" s="T266" e="T267">((atmet ein)) </ts><ts n="e" id="Seg_5637" s="T267" e="T268">denkt, das is doch genügend Geld, </ts><ts n="e" id="Seg_5639" s="T268" e="T269">((atmet ein)) </ts><ts n="e" id="Seg_5641" s="T269" e="T270">das muss doch gehn und das ging vor sieben acht Jahren auch noch ganz gut </ts><ts n="e" id="Seg_5643" s="T270" e="T271">((atmet ein)) </ts><ts n="e" id="Seg_5645" s="T271" e="T272">ähmm und das hat sich eingeschlichen so Stück für Stück </ts><ts n="e" id="Seg_5647" s="T272" e="T273">und irgendwann hat man gemerkt, </ts><ts n="e" id="Seg_5649" s="T273" e="T274">warum ist das Konto auf einmal im/ immer leer und immer früher, früher leer. </ts><ts n="e" id="Seg_5651" s="T274" e="T275">Der Monat wird immer kürzer </ts><ts n="e" id="Seg_5653" s="T275" e="T276">• • </ts><ts n="e" id="Seg_5655" s="T276" e="T277">irgendwie </ts><ts n="e" id="Seg_5657" s="T277" e="T278">((atmet ein)) </ts><ts n="e" id="Seg_5659" s="T278" e="T279">und ähm </ts><ts n="e" id="Seg_5661" s="T279" e="T280">((atmet ein)) </ts><ts n="e" id="Seg_5663" s="T280" e="T281">es hat auch ne Weile gedauert, bis das sich gesetzt hat, dass das Geld weniger wird, </ts><ts n="e" id="Seg_5665" s="T281" e="T282">• • </ts><ts n="e" id="Seg_5667" s="T282" e="T283">ja dass man verstanden hat, das is gar nicht, weil wir im Urlaub gefahren sind, </ts><ts n="e" id="Seg_5669" s="T283" e="T284">sondern das is, weil wir s allgemein nich mehr hinkriegen und </ts><ts n="e" id="Seg_5671" s="T284" e="T285">((atmet ein)) </ts><ts n="e" id="Seg_5673" s="T285" e="T286">• • </ts><ts n="e" id="Seg_5675" s="T286" e="T287">rea</ts><ts n="e" id="Seg_5677" s="T287" e="T288">gieren dauert. </ts><ts n="e" id="Seg_5679" s="T288" e="T289">((atmet ein)) </ts></ts><ts n="sc" id="Seg_5680" s="T292" e="T293"><ts n="e" id="Seg_5682" s="T292" e="T293">Ja. </ts></ts><ts n="sc" id="Seg_5683" s="T306" e="T308"><ts n="e" id="Seg_5685" s="T306" e="T307">• • </ts><ts n="e" id="Seg_5687" s="T307" e="T308">((räuspert sich))˙ </ts></ts><ts n="sc" id="Seg_5688" s="T332" e="T333"><ts n="e" id="Seg_5690" s="T332" e="T333">Ḿhm̀˙ </ts></ts><ts n="sc" id="Seg_5691" s="T334" e="T335"><ts n="e" id="Seg_5693" s="T334" e="T335">Ḿhm̀˙ </ts></ts><ts n="sc" id="Seg_5694" s="T397" e="T398"><ts n="e" id="Seg_5696" s="T397" e="T398">Ähm˙ </ts></ts><ts n="sc" id="Seg_5697" s="T399" e="T402"><ts n="e" id="Seg_5699" s="T399" e="T400">Ich würd da ((atmet ein)) </ts><ts n="e" id="Seg_5701" s="T400" e="T401">• • • </ts><ts n="e" id="Seg_5703" s="T401" e="T402">gerne was zu sagen. </ts></ts><ts n="sc" id="Seg_5704" s="T403" e="T437"><ts n="e" id="Seg_5706" s="T403" e="T404">Ja. </ts><ts n="e" id="Seg_5708" s="T404" e="T405">((atmet ein)) </ts><ts n="e" id="Seg_5710" s="T405" e="T406">Ich denke auch… </ts><ts n="e" id="Seg_5712" s="T406" e="T407">Also das Problem is, </ts><ts n="e" id="Seg_5714" s="T407" e="T408">dass wir • ähm mehr mehr spüren, wie der Standard in unserer Gesellschaft gestiegen is. </ts><ts n="e" id="Seg_5716" s="T408" e="T409">Es sind unge… </ts><ts n="e" id="Seg_5718" s="T409" e="T410">Also es sind Erwartungshaltungen da, </ts><ts n="e" id="Seg_5720" s="T410" e="T411">((atmet ein)) </ts><ts n="e" id="Seg_5722" s="T411" e="T412">was wir </ts><ts n="e" id="Seg_5724" s="T412" e="T413">• • </ts><ts n="e" id="Seg_5726" s="T413" e="T414">leisten </ts><ts n="e" id="Seg_5728" s="T414" e="T415">sollen und die sind </ts><ts n="e" id="Seg_5730" s="T415" e="T416">sehr hoch. </ts><ts n="e" id="Seg_5732" s="T416" e="T417">Auch </ts><ts n="e" id="Seg_5734" s="T417" e="T418">wie </ts><ts n="e" id="Seg_5736" s="T418" e="T419">wir zum Beispiel unsere Kinder versorgen, </ts><ts n="e" id="Seg_5738" s="T419" e="T420">((atmet ein)) </ts><ts n="e" id="Seg_5740" s="T420" e="T421">ähmmm˙ </ts><ts n="e" id="Seg_5742" s="T421" e="T422">((atmet ein)) </ts><ts n="e" id="Seg_5744" s="T422" e="T423">wie wir sie </ts><ts n="e" id="Seg_5746" s="T423" e="T424">((atmet ein)) </ts><ts n="e" id="Seg_5748" s="T424" e="T425">• • </ts><ts n="e" id="Seg_5750" s="T425" e="T426">vorwärts bringen, fördern, </ts><ts n="e" id="Seg_5752" s="T426" e="T427">((atmet ein)) </ts><ts n="e" id="Seg_5754" s="T427" e="T428">ähmm wie präsent wir als Eltern sind, </ts><ts n="e" id="Seg_5756" s="T428" e="T429">wie wie gut wir uns um unsere Großeltern kümmern zum Beispiel, </ts><ts n="e" id="Seg_5758" s="T429" e="T430">((atmet ein)) </ts><ts n="e" id="Seg_5760" s="T430" e="T431">wieviele Arzttermine wir wahrnehmen sollen. </ts><ts n="e" id="Seg_5762" s="T431" e="T432">((atmet ein)) </ts><ts n="e" id="Seg_5764" s="T432" e="T433">((stammelt)) </ts><ts n="e" id="Seg_5766" s="T433" e="T434">Früher konnte man ne Woche lang — auch ich noch — in/ </ts><ts n="e" id="Seg_5768" s="T434" e="T435">((atmet ein)) </ts><ts n="e" id="Seg_5770" s="T435" e="T436">mit der gleichen Kleidung in die Schule kommen und hatte nachmittags Spielkleidung an. </ts><ts n="e" id="Seg_5772" s="T436" e="T437">Das war bei mir au noch so. </ts></ts><ts n="sc" id="Seg_5773" s="T438" e="T453"><ts n="e" id="Seg_5775" s="T438" e="T439">Das wär bei meinen Kindern undenkbar, die wärn untendurch, das wär… </ts><ts n="e" id="Seg_5777" s="T439" e="T440">((atmet ein)) </ts><ts n="e" id="Seg_5779" s="T440" e="T441">Äh da… </ts><ts n="e" id="Seg_5781" s="T441" e="T442">Also wir haben einen anderen Standard </ts><ts n="e" id="Seg_5783" s="T442" e="T443">und die Erwartungshaltung </ts><ts n="e" id="Seg_5785" s="T443" e="T444">is </ts><ts n="e" id="Seg_5787" s="T444" e="T445">unglaublich hoch, • was </ts><ts n="e" id="Seg_5789" s="T445" e="T446">man leisten muss </ts><ts n="e" id="Seg_5791" s="T446" e="T447">und das </ts><ts n="e" id="Seg_5793" s="T447" e="T448">tut </ts><ts n="e" id="Seg_5795" s="T448" e="T449">man dann als braver Bürger. </ts><ts n="e" id="Seg_5797" s="T449" e="T450">((atmet ein)) </ts><ts n="e" id="Seg_5799" s="T450" e="T451">Ich will ja alles gut machen. </ts><ts n="e" id="Seg_5801" s="T451" e="T452">((atmet ein)) </ts><ts n="e" id="Seg_5803" s="T452" e="T453">Also und das bringt einen… </ts></ts><ts n="sc" id="Seg_5804" s="T454" e="T455"><ts n="e" id="Seg_5806" s="T454" e="T455">Ja. </ts></ts><ts n="sc" id="Seg_5807" s="T456" e="T457"><ts n="e" id="Seg_5809" s="T456" e="T457">Nicht ans Mikro. </ts></ts><ts n="sc" id="Seg_5810" s="T458" e="T459"><ts n="e" id="Seg_5812" s="T458" e="T459">Ja. </ts></ts><ts n="sc" id="Seg_5813" s="T460" e="T463"><ts n="e" id="Seg_5815" s="T460" e="T461">Jawohl. </ts><ts n="e" id="Seg_5817" s="T461" e="T462">((lac</ts><ts n="e" id="Seg_5819" s="T462" e="T463">ht)) </ts></ts><ts n="sc" id="Seg_5820" s="T465" e="T475"><ts n="e" id="Seg_5822" s="T465" e="T466">OK, ich hau nicht ans Mikro aber auf </ts><ts n="e" id="Seg_5824" s="T466" e="T467">‿en Tisch, </ts><ts n="e" id="Seg_5826" s="T467" e="T468">((atmet ein)) </ts><ts n="e" id="Seg_5828" s="T468" e="T469">weil ich find das sehr schwierig. </ts><ts n="e" id="Seg_5830" s="T469" e="T470">Das kann man nicht vergleichen die Vergangenheit und heute. </ts><ts n="e" id="Seg_5832" s="T470" e="T471">Der Standard </ts><ts n="e" id="Seg_5834" s="T471" e="T472">((atmet ein)) </ts><ts n="e" id="Seg_5836" s="T472" e="T473">ähm und der Druck, der auf die Menschen </ts><ts n="e" id="Seg_5838" s="T473" e="T474">((atmet ein)) </ts><ts n="e" id="Seg_5840" s="T474" e="T475">ähm sich auswirkt, den kann man nicht vergleichen. </ts></ts><ts n="sc" id="Seg_5841" s="T513" e="T527"><ts n="e" id="Seg_5843" s="T513" e="T514">(Ich </ts><ts n="e" id="Seg_5845" s="T514" e="T515">möchte) gleich unterbr</ts><ts n="e" id="Seg_5847" s="T515" e="T516">echen, weil… </ts><ts n="e" id="Seg_5849" s="T516" e="T517">Also bis vor drei oder vier Jahren — ich glaub mein Neffe war noch dabei — da wurden Zahnspangen für </ts><ts n="e" id="Seg_5851" s="T517" e="T518">jedes </ts><ts n="e" id="Seg_5853" s="T518" e="T519">Kind </ts><ts n="e" id="Seg_5855" s="T519" e="T520">bezahlt, </ts><ts n="e" id="Seg_5857" s="T520" e="T521">jedes </ts><ts n="e" id="Seg_5859" s="T521" e="T522">Kind </ts><ts n="e" id="Seg_5861" s="T522" e="T523">((atmet ein)) </ts><ts n="e" id="Seg_5863" s="T523" e="T524">un jetzt </ts><ts n="e" id="Seg_5865" s="T524" e="T525">is‿es so, dass nur bei </ts><ts n="e" id="Seg_5867" s="T525" e="T526">Überbiss </ts><ts n="e" id="Seg_5869" s="T526" e="T527">bei ner best… </ts></ts></segmentation><annotation name="en" tierref="TIE20"><ta id="Seg_5870" s="T22" e="T27">So here in Bavaria it was one thirty-six this morning and I'm just not going to go to the hairdresser any time soon, I'm going to cut it myself. </ta><ta id="Seg_5871" s="T27" e="T29">I'll save money somewhere else . </ta><ta id="Seg_5872" s="T31" e="T33">Hairdresser is often not included . </ta><ta id="Seg_5873" s="T258" e="T261">Yes for sure . </ta><ta id="Seg_5874" s="T261" e="T262">So on the one hand also the understanding for the people who live with Hartz Vier . </ta><ta id="Seg_5875" s="T262" e="T263">In any case . </ta><ta id="Seg_5876" s="T263" e="T274">So I think that's also an issue, you can't forget that, but the other thing is that of course you think, that's enough money, that must be possible and that was still going quite well seven or eight years ago umm and that crept in bit by bit and at some point you realised, why is the account suddenly empty in / always empty and always empty earlier, earlier. </ta><ta id="Seg_5877" s="T274" e="T289">The month is getting shorter and shorter somehow and it also took a while for it to sink in that the money was getting less, yes, that you understood that it's not because we went on holiday, but because we generally can't manage it anymore and it takes time to react. </ta><ta id="Seg_5878" s="T292" e="T293">Yes .</ta><ta id="Seg_5879" s="T332" e="T333">Ḿhm̀ ˙</ta><ta id="Seg_5880" s="T334" e="T335">Ḿhm̀ ˙</ta><ta id="Seg_5881" s="T397" e="T398">Erm ˙</ta><ta id="Seg_5882" s="T399" e="T402">I would like to say something about that. </ta><ta id="Seg_5883" s="T403" e="T406">Yes, I think so too ... </ta><ta id="Seg_5884" s="T406" e="T408">So the problem is that we feel more and more how the standard in our society has risen. </ta><ta id="Seg_5885" s="T408" e="T409">There are un ... </ta><ta id="Seg_5886" s="T409" e="T416">So there are expectations of what we should achieve and they are very high . </ta><ta id="Seg_5887" s="T416" e="T431">For example, how we look after our children, how we bring them forward, how we encourage them, how present we are as parents, how well we look after our grandparents, for example, how many doctor's appointments we should attend. </ta><ta id="Seg_5888" s="T431" e="T436">In the past, you could come to school for a week - even me - in / with the same clothes and had play clothes on in the afternoon . </ta><ta id="Seg_5889" s="T436" e="T437">That was still the case with me . </ta><ta id="Seg_5890" s="T438" e="T440">That would be unthinkable with my children, they'd be down and out, that would be ... </ta><ta id="Seg_5891" s="T440" e="T441">Uh there ... </ta><ta id="Seg_5892" s="T441" e="T449">Well, we have a different standard and the expectations are incredibly high, what you have to achieve and then you do it as a good citizen. </ta><ta id="Seg_5893" s="T449" e="T451">I want to do everything well. </ta><ta id="Seg_5894" s="T451" e="T453">So and that brings you ...</ta><ta id="Seg_5895" s="T454" e="T455">Yes .</ta><ta id="Seg_5896" s="T456" e="T457">Not to the microphone . </ta><ta id="Seg_5897" s="T458" e="T459">Yes .</ta><ta id="Seg_5898" s="T460" e="T463">Yes . </ta><ta id="Seg_5899" s="T465" e="T469">OK, I'm not banging on the microphone but on the table, because I find that very difficult. </ta><ta id="Seg_5900" s="T469" e="T470">You can't compare the past and today . </ta><ta id="Seg_5901" s="T470" e="T475">You can't compare the standard um and the pressure that affects people um . </ta><ta id="Seg_5902" s="T513" e="T516">I want to interrupt right now because ... </ta><ta id="Seg_5903" s="T516" e="T527">Well, up until three or four years ago - I think my nephew was still there - braces were paid for every child, every child and now it's only in the case of an overbite with the best ...</ta></annotation><annotation name="akz" tierref="TIE5"><ta id="Seg_5904" s="T444" e="T445">—</ta><ta id="Seg_5905" s="T447" e="T448">—</ta><ta id="Seg_5906" s="T517" e="T518">—</ta></annotation><annotation name="k" tierref="TIE15"><ta id="Seg_5907" s="T332" e="T333">bejahend </ta><ta id="Seg_5908" s="T334" e="T335">bejahend </ta></annotation></segmented-tier><segmented-tier id="TIE6" speaker="SPK3" category="v" type="t" display-name="FB [v]"><timeline-fork start="T50" end="T51"><tli id="T50.TIE6.1"/>
