]]></nts><ts n="HIAT:w" id="Seg_7552" s="T442.TIE6.5" e="T443">tun</ts><nts n="HIAT:ip" id="Seg_7553">.</nts><nts n="HIAT:ip" id="Seg_7554"><![CDATA[ ]]></nts></ts></ts><ts n="sc" id="Seg_7555" s="T476" e="T478"><ts n="HIAT:u" id="Seg_7557" s="T476" e="T478"><nts n="HIAT:ip" id="Seg_7558">(</nts><nts n="HIAT:ip" id="Seg_7559">(</nts><ats n="HIAT:non-pho" id="Seg_7560" s="T476" e="T478">unv.</ats><nts n="HIAT:ip" id="Seg_7561">)</nts><nts n="HIAT:ip" id="Seg_7562">)</nts><nts n="HIAT:ip" id="Seg_7563">˙</nts><nts n="HIAT:ip" id="Seg_7564"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE6"><ts n="sc" id="Seg_7565" s="T44" e="T45"><ts n="e" id="Seg_7567" s="T44" e="T45">Ja. </ts></ts><ts n="sc" id="Seg_7568" s="T48" e="T49"><ts n="e" id="Seg_7570" s="T48" e="T49">Ḿhm̀˙ </ts></ts><ts n="sc" id="Seg_7571" s="T50" e="T75"><ts n="e" id="Seg_7573" s="T50" e="T51">• • </ts><ts n="e" id="Seg_7575" s="T51" e="T52">Ja ne ganze Menge </ts><ts n="e" id="Seg_7577" s="T52" e="T53">(dabei). </ts><ts n="e" id="Seg_7579" s="T53" e="T54">((atmet ein)) </ts><ts n="e" id="Seg_7581" s="T54" e="T55">• • </ts><ts n="e" id="Seg_7583" s="T55" e="T56">Ich muss aufpassen, dass ich also wenig Heizung </ts><ts n="e" id="Seg_7585" s="T56" e="T57">((1,1s)) </ts><ts n="e" id="Seg_7587" s="T57" e="T58">nehme von meiner </ts><ts n="e" id="Seg_7589" s="T58" e="T59">((atmet ein)) </ts><ts n="e" id="Seg_7591" s="T59" e="T60">((1,4s)) </ts><ts n="e" id="Seg_7593" s="T60" e="T61">((atmet aus)) </ts><ts n="e" id="Seg_7595" s="T61" e="T63">• • • </ts><ts n="e" id="Seg_7597" s="T63" e="T64">meinen Räumen. </ts><ts n="e" id="Seg_7599" s="T64" e="T65">Nun ich hab also die Räume kalt. </ts><ts n="e" id="Seg_7601" s="T65" e="T66">• • </ts><ts n="e" id="Seg_7603" s="T66" e="T67">Hab nur </ts><ts n="e" id="Seg_7605" s="T67" e="T68">einen </ts><ts n="e" id="Seg_7607" s="T68" e="T69">Raum, den heiz ich im Winter über und jetzt ist ja auch oft noch sehr kalt. </ts><ts n="e" id="Seg_7609" s="T69" e="T70">• • </ts><ts n="e" id="Seg_7611" s="T70" e="T71">Die Küche ist kalt, die Zimmer sind kalt, das Bad ist kalt, ich wasch mich im Kalten </ts><ts n="e" id="Seg_7613" s="T71" e="T72">• • • </ts><ts n="e" id="Seg_7615" s="T72" e="T73">und äh um noch Strom zu sparen, sitz ich bei </ts><ts n="e" id="Seg_7617" s="T73" e="T74">Kerzenlicht </ts><ts n="e" id="Seg_7619" s="T74" e="T75">und es is immer en kleines Weihnachten. </ts></ts><ts n="sc" id="Seg_7620" s="T80" e="T82"><ts n="e" id="Seg_7622" s="T80" e="T81">Das is </ts><ts n="e" id="Seg_7624" s="T81" e="T82">keine, das is Notwendigkeit. </ts></ts><ts n="sc" id="Seg_7625" s="T84" e="T85"><ts n="e" id="Seg_7627" s="T84" e="T85">Sonst kommt überhaupt/ da geht überhaupt nix mehr. </ts></ts><ts n="sc" id="Seg_7628" s="T87" e="T91"><ts n="e" id="Seg_7630" s="T87" e="T88">• </ts><ts n="e" id="Seg_7632" s="T88" e="T89">Muss so wenig wie möglich also… </ts><ts n="e" id="Seg_7634" s="T89" e="T90">((atmet ein)) </ts><ts n="e" id="Seg_7636" s="T90" e="T91">I ich zahl im Monat noch einunddreißig Mark Strom. </ts></ts><ts n="sc" id="Seg_7637" s="T92" e="T99"><ts n="e" id="Seg_7639" s="T92" e="T93">• • </ts><ts n="e" id="Seg_7641" s="T93" e="T94">Äh Euro. </ts><ts n="e" id="Seg_7643" s="T94" e="T95">Entschuldigung. </ts><ts n="e" id="Seg_7645" s="T95" e="T96">• • • </ts><ts n="e" id="Seg_7647" s="T96" e="T97">Und </ts><ts n="e" id="Seg_7649" s="T97" e="T98">das muss, </ts><ts n="e" id="Seg_7651" s="T98" e="T99">• das muss eingespart werden. </ts></ts><ts n="sc" id="Seg_7652" s="T101" e="T102"><ts n="e" id="Seg_7654" s="T101" e="T102">Ja. </ts></ts><ts n="sc" id="Seg_7655" s="T116" e="T117"><ts n="e" id="Seg_7657" s="T116" e="T117">Ich habe nie über meine Verhältnisse gelebt </ts></ts><ts n="sc" id="Seg_7658" s="T301" e="T305"><ts n="e" id="Seg_7660" s="T301" e="T302">Nee. </ts><ts n="e" id="Seg_7662" s="T302" e="T303">((atmet ein)) </ts><ts n="e" id="Seg_7664" s="T303" e="T304">(Da) äh</ts><ts n="e" id="Seg_7666" s="T304" e="T305">m… </ts></ts><ts n="sc" id="Seg_7667" s="T308" e="T380"><ts n="e" id="Seg_7669" s="T308" e="T309">• • </ts><ts n="e" id="Seg_7671" s="T309" e="T310">Ganz kurz nur </ts><ts n="e" id="Seg_7673" s="T310" e="T311">((atmet ein)) </ts><ts n="e" id="Seg_7675" s="T311" e="T312">alss </ts><ts n="e" id="Seg_7677" s="T312" e="T313">• • </ts><ts n="e" id="Seg_7679" s="T313" e="T314">die Zeit war, • wo die Väter im Krieg waren und die Mütter in der </ts><ts n="e" id="Seg_7681" s="T314" e="T315">((atmet ein)) </ts><ts n="e" id="Seg_7683" s="T315" e="T316">äh Kriegswirtschaft arbeiten mussten und </ts><ts n="e" id="Seg_7685" s="T316" e="T317">((atmet ein)) </ts><ts n="e" id="Seg_7687" s="T317" e="T318">wir Mütter/ die Mütter mit Kindern allein zu Hause waren. </ts><ts n="e" id="Seg_7689" s="T318" e="T319">Da ham wir </ts><ts n="e" id="Seg_7691" s="T319" e="T320">((atmet ein)) </ts><ts n="e" id="Seg_7693" s="T320" e="T321">húndért- </ts><ts n="e" id="Seg_7695" s="T321" e="T322">• • • </ts><ts n="e" id="Seg_7697" s="T322" e="T323">-achtundzwanzig Mark </ts><ts n="e" id="Seg_7699" s="T323" e="T324">Familien</ts><ts n="e" id="Seg_7701" s="T324" e="T325">unterhalt bekommen. </ts><ts n="e" id="Seg_7703" s="T325" e="T326">Hundert ((unv.))/ hundertachtundzwanzig Mark. </ts><ts n="e" id="Seg_7705" s="T326" e="T327">((atmet ein)) </ts><ts n="e" id="Seg_7707" s="T327" e="T328">Davon • mussten neununddreißig Mark Miete bezahlt werden, </ts><ts n="e" id="Seg_7709" s="T328" e="T329">((atmet ein)) </ts><ts n="e" id="Seg_7711" s="T329" e="T330">Strom und Gas </ts><ts n="e" id="Seg_7713" s="T330" e="T331">((atmet ein)) </ts><ts n="e" id="Seg_7715" s="T331" e="T332">und vom kleinen Rest durften wir leb</ts><ts n="e" id="Seg_7717" s="T332" e="T333">en. </ts><ts n="e" id="Seg_7719" s="T333" e="T334">Das war ein ewiges Affenthe</ts><ts n="e" id="Seg_7721" s="T334" e="T335">ater. </ts><ts n="e" id="Seg_7723" s="T335" e="T336">• • </ts><ts n="e" id="Seg_7725" s="T336" e="T337">((atmet ein)) </ts><ts n="e" id="Seg_7727" s="T337" e="T338">Das ham wir durchgehalten. </ts><ts n="e" id="Seg_7729" s="T338" e="T339">((1,6s)) </ts><ts n="e" id="Seg_7731" s="T339" e="T340">In uns gegenseitig zu unterstützen. </ts><ts n="e" id="Seg_7733" s="T340" e="T341">Ich hab meiner Mutter geholfen, wo ich konnte. </ts><ts n="e" id="Seg_7735" s="T341" e="T342">Sie war in der </ts><ts n="e" id="Seg_7737" s="T342" e="T343">Rüstung, </ts><ts n="e" id="Seg_7739" s="T343" e="T344">ich hab sie morgens um fünf an die </ts><ts n="e" id="Seg_7741" s="T344" e="T345">Bahn </ts><ts n="e" id="Seg_7743" s="T345" e="T346">gebracht, </ts><ts n="e" id="Seg_7745" s="T346" e="T347">((atmet ein)) </ts><ts n="e" id="Seg_7747" s="T347" e="T348">hab sie abends wieder abgeholt. </ts><ts n="e" id="Seg_7749" s="T348" e="T349">• • • </ts><ts n="e" id="Seg_7751" s="T349" e="T350">Es war ein </ts><ts n="e" id="Seg_7753" s="T350" e="T351">• </ts><ts n="e" id="Seg_7755" s="T351" e="T352">trauriges, </ts><ts n="e" id="Seg_7757" s="T352" e="T353">• • • </ts><ts n="e" id="Seg_7759" s="T353" e="T354">wirklich trauriges Dasein. </ts><ts n="e" id="Seg_7761" s="T354" e="T355">((atmet ein)) </ts><ts n="e" id="Seg_7763" s="T355" e="T356">Ich musste dann in die Schule, </ts><ts n="e" id="Seg_7765" s="T356" e="T357">((atmet ein)) </ts><ts n="e" id="Seg_7767" s="T357" e="T358">bin dann mit meines Vaters Fahrrad, wenn Luftalarm… </ts><ts n="e" id="Seg_7769" s="T358" e="T359">Ich hatte ne rote Karte. </ts><ts n="e" id="Seg_7771" s="T359" e="T360">Da durft ich bei Luftalarm alleine losfahren, </ts><ts n="e" id="Seg_7773" s="T360" e="T361">weil ich da in der Nähe wohnte, </ts><ts n="e" id="Seg_7775" s="T361" e="T362">((atmet ein)) </ts><ts n="e" id="Seg_7777" s="T362" e="T363">bin aber </ts><ts n="e" id="Seg_7779" s="T363" e="T364">nicht </ts><ts n="e" id="Seg_7781" s="T364" e="T365">nach Hause gefahren, </ts><ts n="e" id="Seg_7783" s="T365" e="T366">((atmet ein)) </ts><ts n="e" id="Seg_7785" s="T366" e="T367">sondern bin nach/ </ts><ts n="e" id="Seg_7787" s="T367" e="T368">((atmet ein)) </ts><ts n="e" id="Seg_7789" s="T368" e="T369">zu meiner Mutter in die • Fabrik gefahrn nach Plagwitz. </ts><ts n="e" id="Seg_7791" s="T369" e="T370">((atmet ein)) </ts><ts n="e" id="Seg_7793" s="T370" e="T371">Das war ungefähr ne halbe Stunde mit dem Fahrrad. </ts><ts n="e" id="Seg_7795" s="T371" e="T372">• • </ts><ts n="e" id="Seg_7797" s="T372" e="T373">((atmet ein)) </ts><ts n="e" id="Seg_7799" s="T373" e="T374">Über mir die • Amis und die • Tommies, </ts><ts n="e" id="Seg_7801" s="T374" e="T375">((atmet ein)) </ts><ts n="e" id="Seg_7803" s="T375" e="T376">die schmissen schon ihre Bomben ab und ich war untendurch </ts><ts n="e" id="Seg_7805" s="T376" e="T377">((atmet ein)) </ts><ts n="e" id="Seg_7807" s="T377" e="T378">und guckte immer, wo einer fiel, </ts><ts n="e" id="Seg_7809" s="T378" e="T379">sodass ich noch eben ge/ vorbeikam, kam zu meiner Mutter an die Fabrik, </ts><ts n="e" id="Seg_7811" s="T379" e="T380">da stand die Tür offen ((atmet ein)) "Komm rein Kind!" erst mal die Tür zu und dann krachte es. </ts></ts><ts n="sc" id="Seg_7812" s="T382" e="T383"><ts n="e" id="Seg_7814" s="T382" e="T383">((unv.))˙ </ts></ts><ts n="sc" id="Seg_7815" s="T384" e="T386"><ts n="e" id="Seg_7817" s="T384" e="T385">Nee </ts><ts n="e" id="Seg_7819" s="T385" e="T386">(wir ham)… </ts></ts><ts n="sc" id="Seg_7820" s="T387" e="T388"><ts n="e" id="Seg_7822" s="T387" e="T388">(Es wa) ((unv.))… </ts></ts><ts n="sc" id="Seg_7823" s="T389" e="T392"><ts n="e" id="Seg_7825" s="T389" e="T390">Es warn andere Z</ts><ts n="e" id="Seg_7827" s="T390" e="T391">eiten. </ts><ts n="e" id="Seg_7829" s="T391" e="T392">S war ne. </ts></ts><ts n="sc" id="Seg_7830" s="T395" e="T400"><ts n="e" id="Seg_7832" s="T395" e="T396">Vor allen Dingen war mehr </ts><ts n="e" id="Seg_7834" s="T396" e="T397">Menschlichkeit das war </ts><ts n="e" id="Seg_7836" s="T397" e="T398">vor allen Dingen </ts><ts n="e" id="Seg_7838" s="T398" e="T399">• </ts><ts n="e" id="Seg_7840" s="T399" e="T400">mehr Menschlichkeit. </ts></ts><ts n="sc" id="Seg_7841" s="T412" e="T414"><ts n="e" id="Seg_7843" s="T412" e="T413">Und die sind </ts><ts n="e" id="Seg_7845" s="T413" e="T414">zu hoch. </ts></ts><ts n="sc" id="Seg_7846" s="T415" e="T416"><ts n="e" id="Seg_7848" s="T415" e="T416">((unv.))˙ </ts></ts><ts n="sc" id="Seg_7849" s="T417" e="T418"><ts n="e" id="Seg_7851" s="T417" e="T418">Ja. </ts></ts><ts n="sc" id="Seg_7852" s="T437" e="T438"><ts n="e" id="Seg_7854" s="T437" e="T438">Mhm˙ </ts></ts><ts n="sc" id="Seg_7855" s="T442" e="T443"><ts n="e" id="Seg_7857" s="T442" e="T443">Ja (da) muss man was tun. </ts></ts><ts n="sc" id="Seg_7858" s="T476" e="T478"><ts n="e" id="Seg_7860" s="T476" e="T478">((unv.))˙ </ts></ts></segmentation><annotation name="en" tierref="TIE21"><ta id="Seg_7861" s="T44" e="T45">Yes .</ta><ta id="Seg_7862" s="T48" e="T49">Ḿhm̀ ˙</ta><ta id="Seg_7863" s="T50" e="T53">Yes, quite a lot of them. </ta><ta id="Seg_7864" s="T53" e="T64">I have to be careful that I don't use too much heating in my rooms. </ta><ta id="Seg_7865" s="T64" e="T65">So I have the rooms cold. </ta><ta id="Seg_7866" s="T65" e="T69">I only have one room that I overheat in winter and now it's often still very cold. </ta><ta id="Seg_7867" s="T69" e="T75">The kitchen is cold, the rooms are cold, the bathroom is cold, I wash myself in the cold and, to save electricity, I sit by candlelight and it's always a little Christmas. </ta><ta id="Seg_7868" s="T80" e="T82">That's not a necessity. </ta><ta id="Seg_7869" s="T84" e="T85">Otherwise nothing at all / nothing works at all . </ta><ta id="Seg_7870" s="T87" e="T89">So I have to pay as little as possible ... </ta><ta id="Seg_7871" s="T89" e="T91">I still pay thirty-one marks a month for electricity. </ta><ta id="Seg_7872" s="T92" e="T94">Er Euro . </ta><ta id="Seg_7873" s="T94" e="T95">Sorry . </ta><ta id="Seg_7874" s="T95" e="T99">And that has to be saved . </ta><ta id="Seg_7875" s="T101" e="T102">Yes .</ta><ta id="Seg_7876" s="T116" e="T117">I have never lived beyond my means</ta><ta id="Seg_7877" s="T301" e="T305">Nope . There um ...</ta><ta id="Seg_7878" s="T308" e="T318">Very briefly, it was the time when the fathers were at war and the mothers had to work in the war economy and we mothers / the mothers with children were alone at home. </ta><ta id="Seg_7879" s="T318" e="T326">We got húndért- -twenty-eight marks to support the family . One hundred / one hundred and twenty-eight marks . </ta><ta id="Seg_7880" s="T326" e="T333">Thirty-nine marks of that had to be used to pay the rent, electricity and gas and we were allowed to live on the small remainder. </ta><ta id="Seg_7881" s="T333" e="T336">That was an eternal monkey business . </ta><ta id="Seg_7882" s="T336" e="T339">We stuck it out . </ta><ta id="Seg_7883" s="T339" e="T340">In supporting each other . </ta><ta id="Seg_7884" s="T340" e="T341">I helped my mum wherever I could. </ta><ta id="Seg_7885" s="T341" e="T348">She was in the armour, I took her to the train at five in the morning and picked her up again in the evening. </ta><ta id="Seg_7886" s="T348" e="T354">It was a sad, really sad existence. </ta><ta id="Seg_7887" s="T354" e="T358">Then I had to go to school, then I rode my father's bike when the air raid siren went off ... </ta><ta id="Seg_7888" s="T358" e="T359">I had a red card. </ta><ta id="Seg_7889" s="T359" e="T369">I was allowed to ride off on my own when the air alarm sounded because I lived nearby, but I didn't ride home but went to / to my mum's factory in Plagwitz. </ta><ta id="Seg_7890" s="T369" e="T371">That was about half an hour by bike . </ta><ta id="Seg_7891" s="T371" e="T380">The Americans and the Tommies were above me , they were already dropping their bombs and I was on the ground and always looked where one fell so that I could just pass by , came to my mum at the factory , the door was open " Come in child ! " first the door closed and then there was a crash . </ta><ta id="Seg_7892" s="T382" e="T383">˙</ta><ta id="Seg_7893" s="T384" e="T386">No, we have ...</ta><ta id="Seg_7894" s="T387" e="T388">It was ...</ta><ta id="Seg_7895" s="T389" e="T392">Those were different times . It was new .</ta><ta id="Seg_7896" s="T395" e="T400">Above all, there was more humanity - above all, there was more humanity. </ta><ta id="Seg_7897" s="T412" e="T414">And they are too high . </ta><ta id="Seg_7898" s="T415" e="T416">˙</ta><ta id="Seg_7899" s="T417" e="T418">Yes .</ta><ta id="Seg_7900" s="T437" e="T438">Mhm ˙</ta><ta id="Seg_7901" s="T442" e="T443">Yes, you have to do something. </ta><ta id="Seg_7902" s="T476" e="T478">˙</ta></annotation><annotation name="akz" tierref="TIE7"><ta id="Seg_7903" s="T67" e="T68">—</ta><ta id="Seg_7904" s="T73" e="T74">—</ta><ta id="Seg_7905" s="T323" e="T324">—</ta><ta id="Seg_7906" s="T342" e="T343">—</ta><ta id="Seg_7907" s="T344" e="T345">— </ta><ta id="Seg_7908" s="T351" e="T352">—</ta><ta id="Seg_7909" s="T363" e="T364">—</ta></annotation><annotation name="k" tierref="TIE16"><ta id="Seg_7910" s="T52" e="T53">lachend </ta><ta id="Seg_7911" s="T97" e="T98">ausatmend </ta><ta id="Seg_7912" s="T116" e="T117">leise </ta><ta id="Seg_7913" s="T437" e="T438">bejahend </ta></annotation></segmented-tier><segmented-tier id="TIE8" speaker="SPK4" category="v" type="t" display-name="EK [v]"><timeline-fork start="T156" end="T157"><tli id="T156.TIE8.1"/>
