nts n="HIAT:ip" id="Seg_8261"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE8"><ts n="sc" id="Seg_8262" s="T156" e="T175"><ts n="e" id="Seg_8264" s="T156" e="T157">• • • </ts><ts n="e" id="Seg_8266" s="T157" e="T158">Es is dramatisch ähm und zwar in den letzten Jahren sehr stark abgestürzt nach äh Untersuchungen </ts><ts n="e" id="Seg_8268" s="T158" e="T159">((atmet ein)) </ts><ts n="e" id="Seg_8270" s="T159" e="T160">äh von ähm äh ungefähr zwei drittel </ts><ts n="e" id="Seg_8272" s="T160" e="T161">((atmet ein)) </ts><ts n="e" id="Seg_8274" s="T161" e="T162">äh vor ähm äh zehn Jahren auf heute knapp über die Hälfte </ts><ts n="e" id="Seg_8276" s="T162" e="T163">((atmet ein)) </ts><ts n="e" id="Seg_8278" s="T163" e="T164">und äh es sind einige nach oben gestiegen </ts><ts n="e" id="Seg_8280" s="T164" e="T165">((atmet ein)) </ts><ts n="e" id="Seg_8282" s="T165" e="T166">aber die </ts><ts n="e" id="Seg_8284" s="T166" e="T167">Mehrzahl </ts><ts n="e" id="Seg_8286" s="T167" e="T168">ist nach unten abgesackt </ts><ts n="e" id="Seg_8288" s="T168" e="T169">äh • und dazu ähm… </ts><ts n="e" id="Seg_8290" s="T169" e="T170">Das ist nicht nur Globali</ts><ts n="e" id="Seg_8292" s="T170" e="T171">sierung. </ts><ts n="e" id="Seg_8294" s="T171" e="T172">((atmet ein)) </ts><ts n="e" id="Seg_8296" s="T172" e="T173">Dazu hat auch ein Teil der Politik und der Gesetzgebung äh in der Bundesrepublik, und zwar von </ts><ts n="e" id="Seg_8298" s="T173" e="T174">wechselnden </ts><ts n="e" id="Seg_8300" s="T174" e="T175">Regierungskoalitionen, beigetragen. </ts></ts><ts n="sc" id="Seg_8301" s="T177" e="T178"><ts n="e" id="Seg_8303" s="T177" e="T178">Ja. </ts></ts><ts n="sc" id="Seg_8304" s="T183" e="T190"><ts n="e" id="Seg_8306" s="T183" e="T184">Ich hab gesacht </ts><ts n="e" id="Seg_8308" s="T184" e="T185">wechselnde wec</ts><ts n="e" id="Seg_8310" s="T185" e="T186">hselnde </ts><ts n="e" id="Seg_8312" s="T186" e="T187">nich </ts><ts n="e" id="Seg_8314" s="T187" e="T188">auch Schwarz-Gelb/ </ts><ts n="e" id="Seg_8316" s="T188" e="T189">auch Schwarz-Gelb war </ts><ts n="e" id="Seg_8318" s="T189" e="T190">nicht ((unv.)). </ts></ts><ts n="sc" id="Seg_8319" s="T519" e="T520"><ts n="e" id="Seg_8321" s="T519" e="T520">Ja. </ts></ts></segmentation><annotation name="en" tierref="TIE22"><ta id="Seg_8322" s="T156" e="T169">It has plummeted dramatically over the last few years, from about two thirds ten years ago to just over half today, and some have risen, but the majority have plummeted,</ta><ta id="Seg_8323" s="T169" e="T172">and it's not just globalisation. </ta><ta id="Seg_8324" s="T172" e="T175">Some of the politics and legislation uh in the Federal Republic of Germany, namely from changing government coalitions, has also contributed to this. </ta><ta id="Seg_8325" s="T177" e="T178">Yes .</ta><ta id="Seg_8326" s="T183" e="T190">I have said changing changing changing not also black-yellow / also black-yellow was not . </ta><ta id="Seg_8327" s="T519" e="T520">Yes .</ta></annotation><annotation name="akz" tierref="TIE9"><ta id="Seg_8328" s="T166" e="T167">—</ta><ta id="Seg_8329" s="T170" e="T171">—</ta><ta id="Seg_8330" s="T173" e="T174">—</ta></annotation></segmented-tier><segmented-tier id="TIE10" speaker="SPK5" category="v" type="t" display-name="HB [v]"><timeline-fork start="T195" end="T196"><tli id="T195.TIE10.1"/>
