><nts n="HIAT:ip" id="Seg_9448"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9450" s="T510.TIE10.1" e="T510.TIE10.2">weiß</ts><nts n="HIAT:ip" id="Seg_9451">,</nts><nts n="HIAT:ip" id="Seg_9452"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9454" s="T510.TIE10.2" e="T510.TIE10.3">das</ts><nts n="HIAT:ip" id="Seg_9455"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9457" s="T510.TIE10.3" e="T510.TIE10.4">ist</ts><nts n="HIAT:ip" id="Seg_9458"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9460" s="T510.TIE10.4" e="T510.TIE10.5">schwer</ts><nts n="HIAT:ip" id="Seg_9461">,</nts><nts n="HIAT:ip" id="Seg_9462"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9464" s="T510.TIE10.5" e="T510.TIE10.6">dass</ts><nts n="HIAT:ip" id="Seg_9465"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9467" s="T510.TIE10.6" e="T510.TIE10.7">man</ts><nts n="HIAT:ip" id="Seg_9468"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9470" s="T510.TIE10.7" e="T510.TIE10.8">den</ts><nts n="HIAT:ip" id="Seg_9471"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9473" s="T510.TIE10.8" e="T510.TIE10.9">Spielraum</ts><nts n="HIAT:ip" id="Seg_9474"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9476" s="T510.TIE10.9" e="T510.TIE10.10">dafür</ts><nts n="HIAT:ip" id="Seg_9477"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9479" s="T510.TIE10.10" e="T511">hat</ts><nts n="HIAT:ip" id="Seg_9480"><![CDATA[ ]]></nts><nts n="HIAT:ip" id="Seg_9481">(</nts><nts n="HIAT:ip" id="Seg_9482">(</nts><ats n="HIAT:non-pho" id="Seg_9483" s="T511" e="T512">atmet ein</ats><nts n="HIAT:ip" id="Seg_9484">)</nts><nts n="HIAT:ip" id="Seg_9485">)</nts><nts n="HIAT:ip" id="Seg_9486"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9488" s="T512" e="T514">nur</ts><nts n="HIAT:ip" id="Seg_9489">…</nts><nts n="HIAT:ip" id="Seg_9490"><![CDATA[ ]]></nts></ts></ts><ts n="sc" id="Seg_9491" s="T521" e="T524"><ts n="HIAT:u" id="Seg_9493" s="T521" e="T524"><ts n="HIAT:w" id="Seg_9495" s="T521" e="T522">Jaja</ts><nts n="HIAT:ip" id="Seg_9496">,</nts><nts n="HIAT:ip" id="Seg_9497"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9499" s="T522" e="T522.TIE10.1">das</ts><nts n="HIAT:ip" id="Seg_9500"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9502" s="T522.TIE10.1" e="T522.TIE10.2">hat</ts><nts n="HIAT:ip" id="Seg_9503"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9505" s="T522.TIE10.2" e="T522.TIE10.3">sich</ts><nts n="HIAT:ip" id="Seg_9506"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_9508" s="T522.TIE10.3" e="T524">geändert</ts><nts n="HIAT:ip" id="Seg_9509">.</nts><nts n="HIAT:ip" id="Seg_9510"><![CDATA[ ]]></nts></ts></ts><ts n="sc" id="Seg_9511" s="T525" e="T526"><ts n="HIAT:u" id="Seg_9513" s="T525" e="T526"><nts n="HIAT:ip" id="Seg_9514">(</nts><nts n="HIAT:ip" id="Seg_9515">(</nts><ats n="HIAT:non-pho" id="Seg_9516" s="T525" e="T526">lacht kurz</ats><nts n="HIAT:ip" id="Seg_9517">)</nts><nts n="HIAT:ip" id="Seg_9518">)</nts><nts n="HIAT:ip" id="Seg_9519">˙</nts><nts n="HIAT:ip" id="Seg_9520"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE10"><ts n="sc" id="Seg_9521" s="T195" e="T237"><ts n="e" id="Seg_9523" s="T195" e="T196">• • </ts><ts n="e" id="Seg_9525" s="T196" e="T197">((atmet ein)) </ts><ts n="e" id="Seg_9527" s="T197" e="T198">Ja Sie müssens mir mal erklären. </ts><ts n="e" id="Seg_9529" s="T198" e="T199">Sie ham ja auch die meisten Sendungen zu Randthemen gemach. </ts><ts n="e" id="Seg_9531" s="T199" e="T200">Sie ham über Managergehälter viele Sendungen gemacht, </ts><ts n="e" id="Seg_9533" s="T200" e="T201">Sie ham unheimlich viel über Hartz Vier Mindestlöhne, </ts><ts n="e" id="Seg_9535" s="T201" e="T202">((atmet ein)) </ts><ts n="e" id="Seg_9537" s="T202" e="T203">aber die Sorgen der Mittelschicht, </ts><ts n="e" id="Seg_9539" s="T203" e="T204">derer, die • • morgens zur Arbeit gehen, </ts><ts n="e" id="Seg_9541" s="T204" e="T205">((atmet ein)) </ts><ts n="e" id="Seg_9543" s="T205" e="T206">die äh das erwirtschaften was nachher </ts><ts n="e" id="Seg_9545" s="T206" e="T207">von </ts><ts n="e" id="Seg_9547" s="T207" e="T208">Staat verteilt wird, </ts><ts n="e" id="Seg_9549" s="T208" e="T209">da sie die Sozialversicherungsbeiträge zahlen, die die Steuern zahlen, </ts><ts n="e" id="Seg_9551" s="T209" e="T210">((atmet ein)) </ts><ts n="e" id="Seg_9553" s="T210" e="T211">die eigentlich den Karren ziehen in Deutschland, über die Sorgen wurde viel zu wenig diskutiert. </ts><ts n="e" id="Seg_9555" s="T211" e="T212">((atmet ein)) </ts><ts n="e" id="Seg_9557" s="T212" e="T213">Und wenn Herr Pofalla gerade sagt, die Mittelschicht wurde ja entlastet </ts><ts n="e" id="Seg_9559" s="T213" e="T214">und nennt als einziges den Arbeitslosenversicherungsbeitrag, </ts><ts n="e" id="Seg_9561" s="T214" e="T215">dann vernachlässigen Sie ja, </ts><ts n="e" id="Seg_9563" s="T215" e="T216">((atmet ein)) </ts><ts n="e" id="Seg_9565" s="T216" e="T217">dass diese schwarz rote Koalition noch mal ganz schön ne Schippe draufgelegt hat mit der größten Steuererhöhung, </ts><ts n="e" id="Seg_9567" s="T217" e="T218">die wir in der Geschichte in der Bundesrepublik hatten </ts><ts n="e" id="Seg_9569" s="T218" e="T219">((atmet ein)) </ts><ts n="e" id="Seg_9571" s="T219" e="T220">mit Mehrwertsteuererhöhung, Versicherungssteuer </ts><ts n="e" id="Seg_9573" s="T220" e="T221">((atmet ein)) </ts><ts n="e" id="Seg_9575" s="T221" e="T222">und vielen anderen • • äh Streichungen, Eigenheimzulage, </ts><ts n="e" id="Seg_9577" s="T222" e="T223">((atmet ein)) </ts><ts n="e" id="Seg_9579" s="T223" e="T224">Pendlerpauschale und vieles andere mehr </ts><ts n="e" id="Seg_9581" s="T224" e="T225">und das hat natürlich besonders die Mittelschicht getroffen. </ts><ts n="e" id="Seg_9583" s="T225" e="T226">((atmet ein)) </ts><ts n="e" id="Seg_9585" s="T226" e="T227">Von dem Aufschwung, der jetzt ist </ts><ts n="e" id="Seg_9587" s="T227" e="T228">((atmet ein)) </ts><ts n="e" id="Seg_9589" s="T228" e="T229">profitiert in erster Linie der Staat. </ts><ts n="e" id="Seg_9591" s="T229" e="T230">Die großen Einnahmen — da können Sie auch lächeln Herr Pofalla — </ts><ts n="e" id="Seg_9593" s="T230" e="T231">die großen Einnahmen sind beim Staat gekommen. </ts><ts n="e" id="Seg_9595" s="T231" e="T232">((atmet ein)) </ts><ts n="e" id="Seg_9597" s="T232" e="T233">Sie ham gesagt "Über die Verhältnisse gelebt". </ts><ts n="e" id="Seg_9599" s="T233" e="T234">Jetzt holen Sie das bei den Bürgern zurück. </ts><ts n="e" id="Seg_9601" s="T234" e="T235">((atmet ein)) </ts><ts n="e" id="Seg_9603" s="T235" e="T236">Netto </ts><ts n="e" id="Seg_9605" s="T236" e="T237">bei den Bürgern • bleibt davon nicht viel über. </ts></ts><ts n="sc" id="Seg_9606" s="T492" e="T514"><ts n="e" id="Seg_9608" s="T492" e="T493">• • • </ts><ts n="e" id="Seg_9610" s="T493" e="T494">((atmet ein)) </ts><ts n="e" id="Seg_9612" s="T494" e="T495">Naja es ist ja ne Investition für die Gesundheit des Kindes/ des Sohnes, insofern </ts><ts n="e" id="Seg_9614" s="T495" e="T496">• • </ts><ts n="e" id="Seg_9616" s="T496" e="T497">äh find ich das erst mal gut dass nicht daran gespart wird, </ts><ts n="e" id="Seg_9618" s="T497" e="T498">denn das wäre ja zu Lasten der Gesundheit des Sohnes. </ts><ts n="e" id="Seg_9620" s="T498" e="T499">((atmet ein)) </ts><ts n="e" id="Seg_9622" s="T499" e="T500">Äh das dafür en hundertdreißig Jahre altes Klavier </ts><ts n="e" id="Seg_9624" s="T500" e="T501">— wenn ich das richtig verstanden hab — </ts><ts n="e" id="Seg_9626" s="T501" e="T502">dafür aufgebracht werden muss, </ts><ts n="e" id="Seg_9628" s="T502" e="T503">((atmet ein)) </ts><ts n="e" id="Seg_9630" s="T503" e="T504">find ich hart. </ts><ts n="e" id="Seg_9632" s="T504" e="T505">Ich ähm bin jetzt… </ts><ts n="e" id="Seg_9634" s="T505" e="T506">Äh weiß jetzt nicht genau, wie teuer die Zahnspange da ist. </ts><ts n="e" id="Seg_9636" s="T506" e="T507">• • </ts><ts n="e" id="Seg_9638" s="T507" e="T508">Man hätte sich überlegen können, ob man frühzeitig mit günstigen • • Beiträgen, </ts><ts n="e" id="Seg_9640" s="T508" e="T509">zum Beispiel ne ((atmet ein)) Zusatzversicherung, hätte abschließen können, </ts><ts n="e" id="Seg_9642" s="T509" e="T510">dass man so was • macht oder nen Sparvertrag oder andere Dinge. </ts><ts n="e" id="Seg_9644" s="T510" e="T511">Ich weiß, das ist schwer, dass man den Spielraum dafür hat </ts><ts n="e" id="Seg_9646" s="T511" e="T512">((atmet ein)) </ts><ts n="e" id="Seg_9648" s="T512" e="T513">n</ts><ts n="e" id="Seg_9650" s="T513" e="T514">ur… </ts></ts><ts n="sc" id="Seg_9651" s="T521" e="T524"><ts n="e" id="Seg_9653" s="T521" e="T522">Jaja, </ts><ts n="e" id="Seg_9655" s="T522" e="T523">das hat sich ge</ts><ts n="e" id="Seg_9657" s="T523" e="T524">ändert. </ts></ts><ts n="sc" id="Seg_9658" s="T525" e="T526"><ts n="e" id="Seg_9660" s="T525" e="T526">((lacht kurz))˙ </ts></ts></segmentation><annotation name="en" tierref="TIE23"><ta id="Seg_9661" s="T195" e="T198">Yes, you'll have to explain it to me. </ta><ta id="Seg_9662" s="T198" e="T199">You also made most of the programmes on marginal topics. </ta><ta id="Seg_9663" s="T199" e="T211">You made a lot of programmes about managers' salaries, you talked a lot about Hartz Four minimum wages, but the concerns of the middle class, of those who go to work in the morning, who earn what is subsequently distributed by the state, because they pay the social security contributions, who pay the taxes, who actually pull the cart in Germany, these concerns were discussed far too little. </ta><ta id="Seg_9664" s="T211" e="T225">And when Mr Pofalla says that the middle class has been relieved and the only thing he mentions is the unemployment insurance contribution, then you are neglecting the fact that this black-red coalition has gone one better with the biggest tax increase that we have had in the history of the Federal Republic with an increase in VAT, insurance tax and many other cuts, home ownership allowance, commuter allowance and much more, and of course this has particularly affected the middle class. </ta><ta id="Seg_9665" s="T225" e="T229">The state is the main beneficiary of the current upturn. </ta><ta id="Seg_9666" s="T229" e="T231">The big revenues - you can smile Mr Pofalla - the big revenues have come from the state. </ta><ta id="Seg_9667" s="T231" e="T233">You said "lived beyond your means". </ta><ta id="Seg_9668" s="T233" e="T234">Now you are taking it back from the citizens. </ta><ta id="Seg_9669" s="T234" e="T237">There is not much left over for the citizens . </ta><ta id="Seg_9670" s="T492" e="T498">Well, it's an investment for the health of the child / son, so I think it's good that no money is being saved on it, because that would be at the expense of the son's health. </ta><ta id="Seg_9671" s="T498" e="T504">I find it hard that a hundred and thirty year old piano - if I've understood correctly - has to be used for this. </ta><ta id="Seg_9672" s="T504" e="T505">I'm now ... </ta><ta id="Seg_9673" s="T505" e="T506">I don't know exactly how expensive the braces are. </ta><ta id="Seg_9674" s="T506" e="T510">You could have thought about whether you could have taken out a supplementary insurance policy early on with favourable premiums, for example, or a savings contract or other things. </ta><ta id="Seg_9675" s="T510" e="T514">I know it's hard to have the leeway to do that but ...</ta><ta id="Seg_9676" s="T521" e="T524">Yes, that has changed. </ta><ta id="Seg_9677" s="T525" e="T526">˙</ta></annotation><annotation name="akz" tierref="TIE11"><ta id="Seg_9678" s="T235" e="T236">—</ta></annotation><annotation name="k" tierref="TIE17"><ta id="Seg_9679" s="T206" e="T207">für: vom </ta></annotation></segmented-tier><segmented-tier id="TIE12" category="nn" type="d" display-name="[nn]"><segmentation name="Event" tierref="TIE12"><ats n="e" id="Seg_9680" s="T237" e="T239">((Publikum applaudiert, 9,4s)) </ats><ats n="e" id="Seg_9681" s="T246" e="T247">((Jemand sagt "Aber die…")) </ats><ats n="e" id="Seg_9682" s="T254" e="T255">((Husten)) </ats><ats n="e" id="Seg_9683" s="T477" e="T483">((Publikum applaudiert, 7,6s)) </ats><ats n="e" id="Seg_9684" s="T487" e="T488">• • • </ats><ats n="e" id="Seg_9685" s="T488" e="T489">((Film wird eingespielt, 2min 9s)) </ats><ats n="e" id="Seg_9686" s="T527" e="T528">((Aufnahme bricht ab)) </ats></segmentation></segmented-tier></segmented-body><conversion-info><basic-transcription-conversion-info><conversion-timeline><conversion-tli id="T0"/><conversion-tli id="T1"/><conversion-tli id="T2"/><conversion-tli id="T3"/><conversion-tli id="T4"/><conversion-tli id="T5"/><conversion-tli id="T6"/><conversion-tli id="T7"/><conversion-tli id="T8"/><conversion-tli id="T9"/><conversion-tli id="T10"/><conversion-tli id="T11"/><conversion-tli id="T12"/><conversion-tli id="T13"/><conversion-tli id="T14"/><conversion-tli id="T15"/><conversion-tli id="T16"/><conversion-tli id="T17"/><conversion-tli id="T18"/><conversion-tli id="T19"/><conversion-tli id="T20"/><conversion-tli id="T21"/><conversion-tli id="T22"/><conversion-tli id="T23"/><conversion-tli id="T24"/><conversion-tli id="T25"/><conversion-tli id="T26"/><conversion-tli id="T27"/><conversion-tli id="T28"/><conversion-tli id="T29"/><conversion-tli id="T30"/><conversion-tli id="T31"/><conversion-tli id="T32"/><conversion-tli id="T33"/><conversion-tli id="T34"/><conversion-tli id="T35"/><conversion-tli id="T36"/><conversion-tli id="T37"/><conversion-tli id="T38"/><conversion-tli id="T39"/><conversion-tli id="T40"/><conversion-tli id="T41"/><conversion-tli id="T42"/><conversion-tli id="T43"/><conversion-tli id="T44"/><conversion-tli id="T45"/><conversion-tli id="T46"/><conversion-tli id="T47"/><conversion-tli id="T48"/><conversion-tli id="T49"/><conversion-tli id="T50"/><conversion-tli id="T51"/><conversion-tli id="T52"/><conversion-tli id="T53"/><conversion-tli id="T54"/><conversion-tli id="T55"/><conversion-tli id="T56"/><conversion-tli id="T57"/><conversion-tli id="T58"/><conversion-tli id="T59"/><conversion-tli id="T60"/><conversion-tli id="T61"/><conversion-tli id="T62"/><conversion-tli